// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp) public {
        vm.assume(timestamp > 0);
        vm.warp(timestamp);
        vm.roll(blockNum);

        address actor1 = makeAddr("actor1");
        vm.deal(actor1, 10 ether);
        vm.prank(actor1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1);

        uint256 pastTimeAfterFirst = c.pastBlockTime();
        uint256 balanceAfterFirst = address(c).balance;

        address actor2 = makeAddr("actor2");
        vm.deal(actor2, 10 ether);
        vm.prank(actor2);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(ok2 == false && c.pastBlockTime() == pastTimeAfterFirst && address(c).balance == balanceAfterFirst);
    }
}
